  "source_title": "hypertherm_powermax30_air_service_manual_rev4_808850.pdf",
  "nodes": {
    "Component": [
      {
        "component_id": "comp_front_panel",
        "name": "Front panel",
        "description": "Panel fitted to the front of the power supply; the control board and amperage adjustment knob attach to it.",
        "category": "panel"
      },
      {
        "component_id": "comp_rear_panel",
        "name": "Rear panel",
        "description": "Panel at the rear of the power supply that holds the power switch and ground wire clip.",
        "category": "panel"
      },
      {
        "component_id": "comp_center_panel",
        "name": "Center panel",
        "description": "Panel that interfaces with the base and other power supply components.",
        "category": "panel"
      },
      {
        "component_id": "comp_control_board",
        "name": "Control board",
        "description": "Board connected to the power board by a ribbon cable and attached to the front panel.",
        "category": "control"
      },
      {
        "component_id": "comp_power_board",
        "name": "Power board",
        "description": "Board with connections for the control board, magnetics assembly, and power switch wiring.",
        "category": "electrical"
      },
      {
        "component_id": "comp_plastic_base",
        "name": "Plastic base",
        "description": "Base that attaches to the bottom components of the power supply and supports the magnetics assembly.",
        "category": "housing"
      },
      {
        "component_id": "comp_magnetics_assembly",
        "name": "Magnetics assembly",
        "description": "Assembly containing transformers and inductors mounted on a metal base plate; the components are replaced as a complete assembly.",
        "category": "electrical"
      },
      {
        "component_id": "comp_transformers",
        "name": "Transformers",
        "description": "Electrical components within the magnetics assembly.",
        "category": "electrical"
      },
      {
        "component_id": "comp_inductors",
        "name": "Inductors",
        "description": "Electrical components within the magnetics assembly, including the output inductor.",
        "category": "electrical"
      },
      {
        "component_id": "comp_fan",
        "name": "Fan",
        "description": "Fan on the fan side of the power supply; it is removed during base and magnetics assembly replacement.",
        "category": "cooling"
      },
      {
        "component_id": "comp_air_filter",
        "name": "Air filter",
        "description": "Air filter with a bowl and drain hose; water may be present in the bowl and hose.",
        "category": "air system"
      },
      {
        "component_id": "comp_heat_exchange_coil",
        "name": "Heat exchange coil",
        "description": "Coil removed during base and magnetics assembly replacement.",
        "category": "cooling"
      },
      {
        "component_id": "comp_internal_compressor",
        "name": "Internal compressor",
        "description": "Compressor removed during base and magnetics assembly replacement.",
        "category": "air system"
      },
      {
        "component_id": "comp_power_switch",
        "name": "Power switch",
        "description": "Switch mounted in the rear panel, with connections to the power board and power cord.",
        "category": "electrical"
      },
      {
        "component_id": "comp_power_cord",
        "name": "Power cord",
        "description": "Cord that connects the power supply to the power source.",
        "category": "electrical"
      },
      {
        "component_id": "comp_torch_lead",
        "name": "Torch lead",
        "description": "Lead connected to the power supply and routed through the front panel.",
        "category": "electrical"
      },
      {
        "component_id": "comp_work_lead",
        "name": "Work lead",
        "description": "Lead connected to the power supply and routed through the front panel.",
        "category": "electrical"
      },
      {
        "component_id": "comp_heatsink",
        "name": "Heatsink",
        "description": "Heat-dissipating component in the power supply that the rear panel's internal rectangular box slides over.",
        "category": "cooling"
      },
      {
        "component_id": "comp_component_barrier",
        "name": "Component barrier",
        "description": "Barrier removed and reinstalled as part of access to internal power supply components.",
        "category": "protective"
      },
      {
        "component_id": "comp_power_supply_cover",
        "name": "Power supply cover",
        "description": "Cover removed and reinstalled to access internal power supply components.",
        "category": "housing"
      },
      {
        "component_id": "comp_ground_wire_clip",
        "name": "Ground wire clip",
        "description": "Clip near the top of the rear panel to which the ground wire is connected.",
        "category": "electrical"
      }
    ]
  },
  "relations": []
}
